class Solution {
    public int maximalSquare(char[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int best = 0;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (matrix[r][c] != 49) continue;
                int maxK = Math.min(m - r, n - c);
                for (int k = maxK; k >= 1; k--) {
                    if (allOnes(matrix, r, c, k)) {
                        best = Math.max(best, k * k);
                        break;
                    }
                }
            }
        }
        return best;
    }

    private boolean allOnes(char[][] g, int r, int c, int k) {
        for (int i = r; i < r + k; i++) {
            for (int j = c; j < c + k; j++) {
                if (g[i][j] != 49) return false;
            }
        }
        return true;
    }
}

class Solution {
    public int maximalSquare(char[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] dp = new int[m][n];
        int best = 0;

        for (int i = 0; i < m; i++) {
            dp[i][0] = matrix[i][0] == 49 ? 1 : 0;
            best = Math.max(best, dp[i][0]);
        }
        for (int j = 0; j < n; j++) {
            dp[0][j] = matrix[0][j] == 49 ? 1 : 0;
            best = Math.max(best, dp[0][j]);
        }

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] == 49) {
                    int side = Math.min(dp[i - 1][j], dp[i][j - 1]);
                    side = Math.min(side, dp[i - 1][j - 1]);
                    dp[i][j] = side + 1;
                    best = Math.max(best, dp[i][j]);
                }
            }
        }
        return best * best;
    }
}

class Solution {
    public int maximalSquare(char[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] dp = new int[n];
        int best = 0;

        for (int j = 0; j < n; j++) {
            dp[j] = matrix[0][j] == 49 ? 1 : 0;
            best = Math.max(best, dp[j]);
        }

        for (int i = 1; i < m; i++) {
            int prev = dp[0];
            dp[0] = matrix[i][0] == 49 ? 1 : 0;
            best = Math.max(best, dp[0]);

            for (int j = 1; j < n; j++) {
                int temp = dp[j];
                if (matrix[i][j] == 49) {
                    int side = Math.min(dp[j], dp[j - 1]);
                    side = Math.min(side, prev);
                    dp[j] = side + 1;
                    best = Math.max(best, dp[j]);
                } else {
                    dp[j] = 0;
                }
                prev = temp;
            }
        }
        return best * best;
    }
}
